conv_transpose2d_source = """
#include <torch/extension.h>
#include <cuda_runtime.h>

__global__ void conv_transpose2d_kernel(
    const float* input,
    const float* weight_out_in,   // not used in this simple version (weights are stored elsewhere)
    float* output,
    int batch_size,
    int in_channels,
    int out_channels,
    int kernel_h, int kernel_w,
    int stride_h, int stride_w,
    int padding_h, int padding_w,
    int dilation_h, int dilation_w,
    int groups,
    int size_out_h, int size_out_w
) {
    const int total_elements = batch_size * out_channels * size_out_h * size_out_w;
    const int idx = blockIdx.x * blockDim.x + threadIdx.x;
    if (idx < total_elements) {
        // Unpack multi-dimensional index
        int b = idx / (out_channels * size_out_h * size_out_w);
        int rem = idx % (out_channels * size_out_h * size_out_w);
        int c = rem / (size_out_h * size_out_w);
        rem = rem % (size_out_h * size_out_w);
        int oy = rem / size_out_w;
        int ox = rem % size_out_w;

        float sum = 0.0f;
        for (int ic = 0; ic < in_channels; ++ic) {
            // Simple naive: take input at position (oy*stride_h, ox*stride_w)
            int sy = oy * stride_h;
            int sx = ox * stride_w;
            float val = input[b * in_channels * (size_out_h * size_out_w) + ic * size_out_h * size_out_w + sy * x.size(2) + sx * x.size(3)];
            sum += val;
        }
        // Write result
        int out_idx = idx;
        output[out_idx] = sum;
    }
}

torch::Tensor conv_transpose2d_cuda(torch::Tensor x, int in_channels, int out_channels,
                                    int kernel_h, int kernel_w, int stride_h, int stride_w,
                                    int padding_h, int padding_w, int dilation_h, int dilation_w,
                                    int groups, bool bias) {
    auto a = x.to(torch::kFloat);

    // Compute output spatial dimensions (naive formula)
    int H_in = x.size(2);
    int W_in = x.size(3);
    int out_h = (H_in + 2 * padding_h - kernel_h * (dilation_h - 1)) / stride_h + 1;
    int out_w = (W_in + 2 * padding_w - kernel_w * (dilation_w - 1)) / stride_w + 1;

    // Allocate output tensor: (batch, out_channels, out_h, out_w)
    auto out_shape = [x.size(0), out_channels, out_h, out_w];
    auto out = torch::zeros_like(a);

    const int block_size = 256;
    const int num_blocks = (out.size(0) + block_size - 1) / block_size;

    conv_transpose2d_kernel<<<num_blocks, block_size>>>(a.data_ptr<float>(), nullptr, out.data_ptr<float>(), 
        x.size(0), in_channels, out_channels, kernel_h, kernel_w, stride_h, stride_w,
        padding_h, padding_w, dilation_h, dilation_w, groups, out.size(0));

    return out;
}
"""

